using namespace std;

class Solution {
public:
    int maxScore(vector<int>& nums) {
        int m = nums.size();
        int full = (1 << m) - 1;
        vector<int> dp(1 << m, 0);

        for (int mask = 0; mask <= full; ++mask) {
            int used = __builtin_popcount(mask);
            if (used == m) continue;

            int operation = used / 2 + 1;
            int first = -1;
            for (int i = 0; i < m; ++i) {
                if (!(mask & (1 << i))) {
                    first = i;
                    break;
                }
            }

            for (int j = first + 1; j < m; ++j) {
                if (!(mask & (1 << j))) {
                    int nextMask = mask | (1 << first) | (1 << j);
                    dp[nextMask] = max(
                        dp[nextMask],
                        dp[mask] + operation * gcd(nums[first], nums[j])
                    );
                }
            }
        }

        return dp[full];
    }
};
