class Solution {
public:
    int maxEqualFreq(vector<int>& nums) {
        int n = nums.size();
        vector<int> count(100001, 0);
        vector<int> frequency(n + 1, 0);

        int distinct = 0;
        int maxFrequency = 0;
        int answer = 0;

        for (int i = 0; i < n; ++i) {
            int x = nums[i];
            int oldCount = count[x];

            if (oldCount > 0) {
                --frequency[oldCount];
            } else {
                ++distinct;
            }

            int newCount = ++count[x];
            ++frequency[newCount];
            maxFrequency = max(maxFrequency, newCount);

            bool valid = false;

            if (maxFrequency == 1) {
                valid = true;
            } else if (frequency[maxFrequency] == 1 &&
                       frequency[maxFrequency - 1] == distinct - 1) {
                valid = true;
            }

            if (valid) {
                answer = i + 1;
            }
        }

        return answer;
    }
};
