#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int regionsBySlashes(vector<string>& grid) {
        int n = grid.size();
        int total = n * n * 4;
        vector<int> parent(total), rankv(total, 0);

        iota(parent.begin(), parent.end(), 0);

        function<int(int)> find = [&](int x) {
            return parent[x] == x ? x : parent[x] = find(parent[x]);
        };

        auto unite = [&](int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (rankv[a] < rankv[b]) swap(a, b);
            parent[b] = a;
            if (rankv[a] == rankv[b]) rankv[a]++;
        };

        auto id = [n](int r, int c, int part) {
            return (r * n + c) * 4 + part;
        };

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int top = id(r, c, 0);
                int right = id(r, c, 1);
                int bottom = id(r, c, 2);
                int left = id(r, c, 3);

                if (grid[r][c] == ' ') {
                    unite(top, right);
                    unite(right, bottom);
                    unite(bottom, left);
                } else if (grid[r][c] == '/') {
                    unite(top, right);
                    unite(bottom, left);
                } else {
                    unite(top, left);
                    unite(right, bottom);
                }

                if (r > 0) unite(top, id(r - 1, c, 2));
                if (c > 0) unite(left, id(r, c - 1, 1));
            }
        }

        int regions = 0;
        for (int i = 0; i < total; i++) {
            if (find(i) == i) regions++;
        }
        return regions;
    }
};
