class Solution {
public:
    vector<double> medianSlidingWindow(vector<int>& nums, int k) {
        multiset<int> low, high;
        vector<double> result;
        int targetLow = (k + 1) / 2;

        auto rebalance = [&]() {
            while ((int)low.size() > targetLow) {
                auto it = prev(low.end());
                high.insert(*it);
                low.erase(it);
            }
            while ((int)low.size() < targetLow) {
                auto it = high.begin();
                low.insert(*it);
                high.erase(it);
            }
        };

        auto add = [&](int x) {
            if (low.empty() || x <= *prev(low.end())) {
                low.insert(x);
            } else {
                high.insert(x);
            }
            rebalance();
        };

        auto remove = [&](int x) {
            auto it = low.find(x);
            if (it != low.end()) {
                low.erase(it);
            } else {
                it = high.find(x);
                high.erase(it);
            }
            rebalance();
        };

        for (int i = 0; i < k; ++i) {
            add(nums[i]);
        }

        for (int i = k; ; ++i) {
            if (k % 2 == 1) {
                result.push_back(*prev(low.end()));
            } else {
                long long a = *prev(low.end());
                long long b = *high.begin();
                result.push_back((a + b) / 2.0);
            }

            if (i == (int)nums.size()) {
                break;
            }

            remove(nums[i - k]);
            add(nums[i]);
        }

        return result;
    }
};
