#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<int> getCoprimes(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();
        vector<vector<int>> graph(n);

        for (auto& edge : edges) {
            graph[edge[0]].push_back(edge[1]);
            graph[edge[1]].push_back(edge[0]);
        }

        vector<int> ans(n, -1);
        vector<vector<int>> path(51);

        struct State {
            int node, parent;
            bool exit;
        };

        vector<State> st;
        st.push_back({0, -1, false});

        while (!st.empty()) {
            auto [u, parent, isExit] = st.back();
            st.pop_back();

            if (!isExit) {
                for (int value = 1; value <= 50; ++value) {
                    if (!path[value].empty() && gcd(nums[u], value) == 1) {
                        int candidate = path[value].back();
                        if (ans[u] == -1 || candidate > -1) {
                            if (ans[u] == -1 || 
                                find(path[nums[u]].begin(), path[nums[u]].end(), candidate) == path[nums[u]].end()) {
                                ans[u] = candidate;
                            }
                        }
                    }
