            int n = part.size();

            if (n == 1 || part[0] != '0') {
                res.push_back(part);
            }

            for (int i = 1; i < n; ++i) {
                string left = part.substr(0, i);
                string right = part.substr(i);

                if (left.size() > 1 && left[0] == '0') continue;
                if (right.back() == '0') continue;

                res.push_back(left + "." + right);
            }

            return res;
        };

        vector<string> answer;

        for (int split = 1; split < (int)digits.size(); ++split) {
            string left = digits.substr(0, split);
            string right = digits.substr(split);

            vector<string> first = generate(left);
            vector<string> second = generate(right);

            for (const string& a : first) {
                for (const string& b : second) {
                    answer.push_back("(" + a + ", " + b + ")");
                }
            }
        }

        return answer;
    }
};
