#include <bits/stdc++.h>
using namespace std;

class MKAverage {
    int m, k;
    deque<int> window;
    multiset<int> low, mid, high;
    long long midSum = 0;

    void rebalance() {
        int n = (int)window.size();
        int targetLow = min(k, n);
        int targetHigh = min(k, n - targetLow);

        while ((int)low.size() > targetLow) {
            auto it = prev(low.end());
            int x = *it;
            low.erase(it);
            mid.insert(x);
            midSum += x;
        }

        while ((int)low.size() < targetLow) {
            if (!mid.empty()) {
                auto it = mid.begin();
                int x = *it;
                mid.erase(it);
                midSum -= x;
                low.insert(x);
            } else if (!high.empty()) {
                auto it = high.begin();
                int x = *it;
                high.erase(it);
                low.insert(x);
            }
        }

        while ((int)high.size() > targetHigh) {
            auto it = high.begin();
            int x = *it;
            high.erase(it);
            mid.insert(x);
            midSum += x;
        }

        while ((int)high.size() < targetHigh) {
            auto it = prev(mid.end());
            int x = *it;
            mid.erase(it);
            midSum -= x;
            high.insert(x);
        }
    }

    void insertValue(int num) {
        if (!low.empty() && num <= *low.rbegin()) {
            low.insert(num);
        } else if (!high.empty() && num >= *high.begin()) {
            high.insert(num);
        } else {
            mid.insert(num);
            midSum += num;
        }
    }

    void eraseValue(int num) {
        auto it = low.find(num);
        if (it != low.end()) {
            low.erase(it);
            return;
        }

        it = mid.find(num);
        if (it != mid.end()) {
            mid.erase(it);
            midSum -= num;
            return;
        }

        it = high.find(num);
        high.erase(it);
    }

public:
    MKAverage(int m, int k) : m(m), k(k) {
    }

    void addElement(int num) {
        window.push_back(num);
        insertValue(num);

        if ((int)window.size() > m) {
            eraseValue(window.front());
            window.pop_front();
        }

        rebalance();
    }

    int calculateMKAverage() {
        if ((int)window.size() < m) {
            return -1;
        }
        return (int)(midSum / (m - 2 * k));
    }
};
