class Solution {
public:
    bool canCross(vector<int>& stones) {
        int n = stones.size();

        unordered_map<int, int> index;
        index.reserve(n * 2);
        for (int i = 0; i < n; ++i) {
            index[stones[i]] = i;
        }

        vector<unordered_set<int>> reachable(n);
        reachable[0].insert(0);

        for (int i = 0; i < n; ++i) {
            for (int lastJump : reachable[i]) {
                for (int delta = -1; delta <= 1; ++delta) {
                    long long jump = (long long)lastJump + delta;
                    if (jump <= 0 || jump > INT_MAX) continue;

                    long long nextPosition = (long long)stones[i] + jump;
                    if (nextPosition > INT_MAX) continue;

                    auto it = index.find((int)nextPosition);
                    if (it == index.end()) continue;

                    int nextIndex = it->second;
                    if (nextIndex == n - 1) return true;
                    reachable[nextIndex].insert((int)jump);
                }
            }
        }

        return false;
    }
};
