class Solution {
public:
    int maxCompatibilitySum(vector<vector<int>>& students, vector<vector<int>>& mentors) {
        int m = students.size();
        int n = students[0].size();

        vector<vector<int>> score(m, vector<int>(m));
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < m; ++j) {
                for (int k = 0; k < n; ++k) {
                    if (students[i][k] == mentors[j][k]) {
                        ++score[i][j];
                    }
                }
            }
        }

        vector<int> dp(1 << m, -1);
        dp[0] = 0;

        for (int mask = 0; mask < (1 << m); ++mask) {
            if (dp[mask] == -1) continue;

            int student = __builtin_popcount(mask);
            if (student == m) continue;

            for (int mentor = 0; mentor < m; ++mentor) {
                if ((mask & (1 << mentor)) == 0) {
                    int nextMask = mask | (1 << mentor);
                    dp[nextMask] = max(dp[nextMask], dp[mask] + score[student][mentor]);
                }
            }
        }

        return dp[(1 << m) - 1];
    }
};
