class Solution {
public:
    int maxTotalFruits(vector<vector<int>>& fruits, int startPos, int k) {
        int n = fruits.size();
        int left = 0;
        long long current = 0, answer = 0;

        auto requiredSteps = [&](int l, int r) -> long long {
            int leftPos = fruits[l][0];
            int rightPos = fruits[r][0];

            if (rightPos <= startPos) {
                return startPos - leftPos;
            }
            if (leftPos >= startPos) {
                return rightPos - startPos;
            }

            long long goLeftFirst =
                2LL * (startPos - leftPos) + (rightPos - startPos);
            long long goRightFirst =
                (startPos - leftPos) + 2LL * (rightPos - startPos);

            return min(goLeftFirst, goRightFirst);
        };

        for (int right = 0; right < n; ++right) {
            current += fruits[right][1];

            while (left <= right && requiredSteps(left, right) > k) {
                current -= fruits[left][1];
                ++left;
            }

            answer = max(answer, current);
        }

        return (int)answer;
    }
};
