#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        sort(flowers.begin(), flowers.end());
        int n = flowers.size();

        int p = lower_bound(flowers.begin(), flowers.end(), target) - flowers.begin();

        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            pref[i + 1] = pref[i] + flowers[i];
        }

        long long answer = 0;

        for (int m = 0; m <= p; ++m) {
            long long completeCost =
                1LL * target * (p - m) - (pref[p] - pref[m]);

            if (completeCost > newFlowers) continue;

            long long beauty = 1LL * (n - m) * full;

            if (m == 0) {
                answer = max(answer, beauty);
                continue;
            }

            long long remaining = newFlowers - completeCost;
            int low = 0, high = target - 1;

            while (low < high) {
                int mid = low + (high - low + 1) / 2;
                int idx = lower_bound(flowers.begin(), flowers.begin() + m, mid) - flowers.begin();
                long long cost = 1LL * mid * idx - pref[idx];

                if (cost <= remaining) {
                    low = mid;
                } else {
                    high = mid - 1;
                }
            }

            beauty += 1LL * low * partial;
            answer = max(answer, beauty);
        }

        return answer;
    }
};
