class Solution {
public:
    int minMalwareSpread(vector<vector<int>>& graph, vector<int>& initial) {
        int n = graph.size();
        vector<bool> isInitial(n, false);
        for (int x : initial) isInitial[x] = true;

        vector<int> component(n, -1);
        vector<int> compSize;
        int compCount = 0;

        for (int i = 0; i < n; ++i) {
            if (isInitial[i] || component[i] != -1) continue;

            queue<int> q;
            q.push(i);
            component[i] = compCount;
            int size = 0;

            while (!q.empty()) {
                int u = q.front();
                q.pop();
                ++size;

                for (int v = 0; v < n; ++v) {
                    if (!isInitial[v] && graph[u][v] && component[v] == -1) {
                        component[v] = compCount;
                        q.push(v);
                    }
                }
            }

            compSize.push_back(size);
            ++compCount;
        }

        vector<int> owner(compCount, -2);
        vector<int> saved(n, 0);

        for (int source : initial) {
            for (int v = 0; v < n; ++v) {
                if (component[v] == -1 || !graph[source][v]) continue;

                int c = component[v];

                if (owner[c] == -2) {
                    owner[c] = source;
                    saved[source] += compSize[c];
                } else if (owner[c] != source && owner[c] != -1) {
                    saved[owner[c]] -= compSize[c];
                    owner[c] = -1;
                }
            }
        }

        int answer = initial[0];
        for (int x : initial) {
            if (saved[x] > saved[answer] ||
                (saved[x] == saved[answer] && x < answer)) {
                answer = x;
            }
        }

        return answer;
    }
};
