class Solution {
public:
    bool isScramble(string s1, string s2) {
        int n = s1.size();
        if (n != (int)s2.size()) return false;

        vector<vector<vector<int>>> memo(
            n, vector<vector<int>>(n, vector<int>(n + 1, -1))
        );

        function<bool(int, int, int)> solve = [&](int i, int j, int len) -> bool {
            int &res = memo[i][j][len];
            if (res != -1) return res;

            if (s1.compare(i, len, s2, j, len) == 0)
                return res = true;

            int cnt[26] = {};
            for (int k = 0; k < len; ++k) {
                ++cnt[s1[i + k] - 'a'];
                --cnt[s2[j + k] - 'a'];
            }

            for (int c = 0; c < 26; ++c) {
                if (cnt[c] != 0)
                    return res = false;
