            for (int cut = 1; cut < len; ++cut) {
                if (solve(i, j, cut) &&
                    solve(i + cut, j + cut, len - cut)) {
                    return res = true;
                }

                if (solve(i, j + len - cut, cut) &&
                    solve(i + cut, j, len - cut)) {
                    return res = true;
                }
            }

            return res = false;
        };

        return solve(0, 0, n);
    }
};
