class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        int m = target.size();
        int full = 1 << m;
        const int INF = 1e9;

        vector<int> dp(full, INF);
        dp[0] = 0;

        for (int mask = 0; mask < full; ++mask) {
            if (dp[mask] == INF) continue;

            for (const string& sticker : stickers) {
                int nextMask = mask;

                for (char c : sticker) {
                    for (int i = 0; i < m; ++i) {
                        if (!(nextMask & (1 << i)) && target[i] == c) {
                            nextMask |= 1 << i;
                            break;
                        }
                    }
                }

                dp[nextMask] = min(dp[nextMask], dp[mask] + 1);
            }
        }

        return dp[full - 1] == INF ? -1 : dp[full - 1];
    }
};
