#include <bits/stdc++.h>
using namespace std;

class Solution {
    pair<int, int> memo[29][29][29];

    pair<int, int> solve(int n, int a, int b) {
        if (a + b == n + 1) return {1, 1};

        if (memo[n][a][b].first != 0) {
            return memo[n][a][b];
        }

        bool possible[30][30] = {};
        possible[0][0] = true;

        auto addWinner = [](pair<int, int> state, int winner, int a, int b) {
            state.first += (winner < a);
            state.second += (winner < b);
            return state;
        };

        for (int i = 1; i <= n / 2; ++i) {
            int j = n + 1 - i;
            bool nextPossible[30][30] = {};

            for (int x = 0; x < 30; ++x) {
                for (int y = 0; y < 30; ++y) {
                    if (!possible[x][y]) continue;

                    if (i == a || j == a) {
                        auto state = addWinner({x, y}, a, a, b);
                        nextPossible[state.first][state.second] = true;
                    } else if (i == b || j == b) {
                        auto state = addWinner({x, y}, b, a, b);
                        nextPossible[state.first][state.second] = true;
                    } else {
                        auto state1 = addWinner({x, y}, i, a, b);
                        auto state2 = addWinner({x, y}, j, a, b);
                        nextPossible[state1.first][state1.second] = true;
                        nextPossible[state2.first][state2.second] = true;
                    }
                }
            }

            memcpy(possible, nextPossible, sizeof(possible));
        }

        if (n % 2 == 1) {
            int middle = (n + 1) / 2;
            bool nextPossible[30][30] = {};

            for (int x = 0; x < 30; ++x) {
                for (int y = 0; y < 30; ++y) {
                    if (!possible[x][y]) continue;
                    auto state = addWinner({x, y}, middle, a, b);
                    nextPossible[state.first][state.second] = true;
                }
            }

            memcpy(possible, nextPossible, sizeof(possible));
        }

        int nextN = (n + 1) / 2;
        int earliest = INT_MAX;
        int latest = 0;

        for (int x = 0; x < 30; ++x) {
            for (int y = 0; y < 30; ++y) {
                if (!possible[x][y]) continue;

                int nextA = x + 1;
                int nextB = y + 1;
                auto result = solve(nextN, nextA, nextB);

                earliest = min(earliest, result.first + 1);
                latest = max(latest, result.second + 1);
            }
        }

        return memo[n][a][b] = {earliest, latest};
    }

public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memset(memo, 0, sizeof(memo));
        auto result = solve(n, firstPlayer, secondPlayer);
        return {result.first, result.second};
    }
};
