    vector<int> kWeakestRows(vector<vector<int>>& mat, int k) {
        vector<pair<int, int>> rows;

        for (int i = 0; i < mat.size(); ++i) {
            int soldiers = 0;
            for (int value : mat[i]) {
                soldiers += value;
            }
            rows.push_back({soldiers, i});
        }

        sort(rows.begin(), rows.end());

        vector<int> answer;
        for (int i = 0; i < k; ++i) {
            answer.push_back(rows[i].second);
        }

        return answer;
    }
