#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    bool isSolvable(vector<string>& words, string result) {
        vector<string> revWords = words;
        for (string& word : revWords) {
            reverse(word.begin(), word.end());
        }
        reverse(result.begin(), result.end());

        vector<bool> leading(26, false);
        for (const string& word : words) {
            if (word.size() > 1) leading[word[0] - 'A'] = true;
        }
        if (result.size() > 1) leading[result.back() - 'A'] = true;

        vector<int> mapping(26, -1);
        vector<bool> used(10, false);

        int maxLen = result.size();
        for (const string& word : words) {
            maxLen = max(maxLen, (int)word.size());
        }

        int distinct = 0;
        vector<bool> seen(26, false);
        for (const string& word : words) {
            for (char c : word) {
                if (!seen[c - 'A']) {
                    seen[c - 'A'] = true;
                    ++distinct;
                }
            }
        }
        for (char c : result) {
            if (!seen[c - 'A']) {
                seen[c - 'A'] = true;
                ++distinct;
            }
        }
        if (distinct > 10) return false;

        function<bool(int, int, int)> dfs = [&](int col, int index, int sum) {
            if (col == maxLen) {
                return sum == 0;
            }

            if (index < (int)words.size()) {
                if (col >= (int)revWords[index].size()) {
                    return dfs(col, index + 1, sum);
                }

                int letter = revWords[index][col] - 'A';
                if (mapping[letter] != -1) {
                    return dfs(col, index + 1, sum + mapping[letter]);
                }

                for (int digit = 0; digit <= 9; ++digit) {
                    if (used[digit]) continue;
                    if (digit == 0 && leading[letter]) continue;

                    mapping[letter] = digit;
                    used[digit] = true;

                    if (dfs(col, index + 1, sum + digit)) {
                        return true;
                    }

                    mapping[letter] = -1;
                    used[digit] = false;
                }
                return false;
            }

            if (col >= (int)result.size()) {
                if (sum % 10 != 0) return false;
                return dfs(col + 1, 0, sum / 10);
            }

            int letter = result[col] - 'A';
            int digit = sum % 10;

            if (mapping[letter] != -1) {
                if (mapping[letter] != digit) return false;
                return dfs(col + 1, 0, sum / 10);
            }

            if (used[digit]) return false;
            if (digit == 0 && leading[letter]) return false;

            mapping[letter] = digit;
            used[digit] = true;

            if (dfs(col + 1, 0, sum / 10)) {
                return true;
            }

            mapping[letter] = -1;
            used[digit] = false;
            return false;
        };

        return dfs(0, 0, 0);
    }
};
